function schema(a){const author=getAuthor(a.authorSlug);return JSON.stringify({'@context':'https://schema.org','@graph':[{'@type':'BlogPosting','headline':a.headline,'description':a.description,'datePublished':a.publishedDate??publishedAt,'dateModified':a.modifiedDate??modifiedAt,'author':{'@type':'Person','@id':`${origin}${author.profilePath}#person`,name:author.name,url:`${origin}${author.profilePath}`},'publisher':{'@type':'Organization',name:'VDALO',logo:{'@type':'ImageObject',url:`${origin}/v1/assets/vdalo-canonical.png`}},'image':[`${origin}/v1${a.image}`],'mainEntityOfPage':{'@type':'WebPage','@id':`${origin}${a.slug}`},'inLanguage':'uk'},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem',position:1,name:'Головна',item:origin},{'@type':'ListItem',position:2,name:'Блог',item:`${origin}/blog`},{'@type':'ListItem',position:3,name:a.headline,item:`${origin}${a.slug}`}]}]}).replace(/</g,'\\u003c')}
for(const a of articles){a.minutes=readingMinutes((a.bodyHtml||a.sections.map(s=>s.join(' ')).join(' '))+(articlePractice[a.slug]?.html||''));if(articlePractice[a.slug]||a.slug.includes('zbir')||a.slug.includes('zboru'))a.modifiedDate='2026-10-23';}
export function renderSecondPassArticle(slug){
 const a=articles.find(x=>x.slug===slug);if(!a)return '';
 let html=renderPage({origin,full:true});
 const articlePublished=a.publishedDate??publishedAt,articleModified=a.modifiedDate??modifiedAt;
 const imageSeo=articleImageSeo[a.slug]||{alt:a.alt,title:a.headline,caption:"Редакційна ілюстрація до матеріалу VDALO."};
 html=html.replace(/<title>[\s\S]*?<\/title>/,`<title>${e(a.title)}</title>`).replace(/<meta name="description" content="[^"]*">/,`<meta name="description" content="${e(a.description)}">`).replace(/<meta property="og:type" content="[^"]*">/,'<meta property="og:type" content="article">').replace(/<meta property="og:title" content="[^"]*">/,`<meta property="og:title" content="${e(a.title)}">`).replace(/<meta property="og:description" content="[^"]*">/,`<meta property="og:description" content="${e(a.description)}">`).replace(/<meta property="og:url" content="[^"]*">/,`<meta property="og:url" content="${origin}${a.slug}">`).replace(/<link rel="canonical" href="[^"]*">/,`<link rel="canonical" href="${origin}${a.slug}">`).replace(/<script type="application\/ld\+json">[\s\S]*?<\/script>/,`<script type="application/ld+json">${schema(a)}</script>`).replace('</head>',`<meta property="article:published_time" content="${articlePublished}"><meta property="article:modified_time" content="${articleModified}"><meta property="og:image" content="${origin}/v1${a.image}"><meta property="og:image:alt" content="${e(imageSeo.alt)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${e(a.title)}"><meta name="twitter:description" content="${e(a.description)}"><meta name="twitter:image" content="${origin}/v1${a.image}"><link rel="stylesheet" href="/blog.css"><link rel="stylesheet" href="/v1/editorial-seo.css"></head>`);
 const body=a.bodyHtml??a.sections.map(([h,p],i)=>`<section id="${i===0?'start':`part-${i+1}`}" ><h2>${e(h)}</h2><p>${e(p)}</p></section>`).join('');
 const sources=a.bodyHtml?'':a.sources?.length?`<section class="article-sources"><h2>Офіційні джерела</h2><ul>${a.sources.map(([label,url])=>`<li><a href="${e(url)}" rel="noopener noreferrer">${e(label)}</a></li>`).join('')}</ul><p>Інформацію перевірено 9 жовтня 2026 року. Перед застосуванням звірте чинну редакцію правил.</p></section>`:'';
 const [actionHeading,actionCopy]=articleActions[a.slug]??['',''];
 const toc=[...(a.toc??a.sections.map(([heading],i)=>[heading,i===0?'start':`part-${i+1}`])),...(articlePractice[a.slug]?[[articlePractice[a.slug].title,'practice']]:[])];
 const relatedLinks=a.links?.length?`<nav class="article-related-links" aria-label="Пов’язані матеріали"><h2>${a.disableActionSection?'Читайте також':'Пов’язані матеріали'}</h2>${a.links.map(([href,label])=>`<a href="${e(href)}">${e(label)} <span aria-hidden="true">↗</span></a>`).join('')}</nav>`:'';
 const actionSection=a.disableActionSection?relatedLinks:`<section class="article-conclusion"><h2>${e(actionHeading)}</h2><p>${e(actionCopy)}</p>${relatedLinks}</section>`;
 const formatDate=value=>new Intl.DateTimeFormat('uk-UA',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(`${value}T00:00:00Z`)).replace(' р.','');
 const publishedLabel=formatDate(articlePublished),modifiedLabel=formatDate(articleModified);
 const author=getAuthor(a.authorSlug);
 const content=`<main id="main" class="pms-article-page"><div class="article-wrap"><nav class="article-breadcrumbs" aria-label="Навігаційний ланцюжок"><a href="/">Головна</a><span aria-hidden="true">/</span><a href="/blog">Блог</a><span aria-hidden="true">/</span><span aria-current="page">${e(a.tag)}</span></nav><header class="article-header"><p class="article-eyebrow">ПРАКТИЧНИЙ ПОСІБНИК · ${e(a.tag)}</p><h1>${e(a.headline)}</h1><p class="article-lead">${e(a.lead)}</p><div class="article-byline"><span>Автор: <a href="${author.profilePath}">${e(author.name)}</a></span><time datetime="${articlePublished}">Опубліковано ${publishedLabel}</time><time datetime="${articleModified}">Оновлено ${modifiedLabel}</time><span>${a.minutes} хв читання</span></div></header><figure class="article-cover"><img src="/v1${a.image}" width="1200" height="800" alt="${e(imageSeo.alt)}" title="${e(imageSeo.title)}" fetchpriority="high"><figcaption>${e(imageSeo.caption)}</figcaption></figure><div class="article-layout"><aside class="article-toc"><p>У статті</p>${toc.map(([heading,id])=>`<a href="#${e(id)}">${e(heading)}</a>`).join('')}</aside><article class="article-body">${body}${articlePractice[a.slug]?.html||''}${actionSection}${sources}<section class="article-sources"><h2>Про матеріал</h2><p>${e(editorialNotes[a.slug])}</p></section></article></div></div></main>`;
 const rendered=html.replace(/<main id="main">[\s\S]*?<\/main>/,content)
  .replace(/<nav id="navigation"[\s\S]*?<\/nav>/,nav=>nav.replace(/href="#([^\"]+)"/g,'href="/#$1"'))
  .replace(/<footer[\s\S]*?<\/footer>/,foot=>foot.replace(/href="#([^\"]+)"/g,'href="/#$1"'));
 return addAuthorContext(rendered);
}
